// Helper function to extract initials from userName
private fun getInitials(userName: String): String {
    val parts = userName.trim().split(" ").filter { it.isNotEmpty() }
    return when {
        parts.size >= 2 -> (parts[0].firstOrNull()?.toString() ?: "") + (parts[1].firstOrNull()?.toString() ?: "")
        parts.size == 1 && parts[0].length >= 2 -> parts[0].substring(0, 2)
        parts.size == 1 && parts[0].isNotEmpty() -> parts[0].substring(0, 1)
        else -> "--"
    }.uppercase()
}

package dk.zlatan.flotmand.model

import com.google.firebase.firestore.DocumentId

private const val TITLE_MAX_SIZE = 30

data class DinnerEvent(
    @DocumentId val id: String = "",
    val text: String = "",
    val userId: String = ""
)

fun DinnerEvent.getTitle(): String {
    val isLongText = this.text.length > TITLE_MAX_SIZE
    val endRange = if (isLongText) TITLE_MAX_SIZE else this.text.length - 1
    return this.text.substring(IntRange(0, endRange))
}

